class SetupCompanion {
 class OwnedProcessUnsettledException:InvalidOperationException {public OwnedProcessUnsettledException():base("Owned installer still running; private staging retained for inspection.") {}}
 const int Limit=33554432;
 static readonly UTF8Encoding Utf8=new UTF8Encoding(false,true);
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=1048576};
 static string Hash(byte[] value){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(value)).Replace("-","").ToLowerInvariant();}
 static bool SafeName(string name){if(String.IsNullOrEmpty(name)||name.Length>240||name.StartsWith("/")||System.Text.RegularExpressions.Regex.IsMatch(name,@"[\\:\x00-\x1f\x7f]"))return false;foreach(string part in name.Split('/'))if(String.IsNullOrEmpty(part)||part=="."||part==".."||part.EndsWith(".")||part.EndsWith(" ")||System.Text.RegularExpressions.Regex.IsMatch(part,@"^(con|prn|aux|nul|com[1-9]|lpt[1-9])(\.|$)",System.Text.RegularExpressions.RegexOptions.IgnoreCase))return false;return true;}
 static void NoLinks(string file){for(string part=Path.GetFullPath(file);!String.IsNullOrEmpty(part);part=Path.GetDirectoryName(part))if((File.Exists(part)||Directory.Exists(part))&&(File.GetAttributes(part)&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("Linked paths are refused.");}
 static Dictionary<string,byte[]> Payload(){byte[] bytes;using(var resource=Assembly.GetExecutingAssembly().GetManifestResourceStream("DomTTSPayload")){if(resource==null||resource.Length<16||resource.Length>Limit)throw new InvalidDataException("Payload size refused.");bytes=new byte[(int)resource.Length];int offset=0;while(offset<bytes.Length){int n=resource.Read(bytes,offset,bytes.Length-offset);if(n<1)throw new InvalidDataException();offset+=n;}}if(Hash(bytes)!=PayloadIdentity.Sha256)throw new InvalidDataException("Payload hash refused.");var files=new Dictionary<string,byte[]>(StringComparer.Ordinal);var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase);using(var input=new BinaryReader(new MemoryStream(bytes),Utf8)){if(Utf8.GetString(input.ReadBytes(12))!="DOMTTSSETUP1\n")throw new InvalidDataException("Payload magic refused.");uint count=input.ReadUInt32();if(count<2||count>1024)throw new InvalidDataException();for(uint i=0;i<count;i++){if(input.BaseStream.Position+8>bytes.Length)throw new InvalidDataException();uint nl=input.ReadUInt32(),dl=input.ReadUInt32();if(nl<1||nl>960||dl>Limit||input.BaseStream.Position+nl+dl>bytes.Length)throw new InvalidDataException("Entry size refused.");string name=Utf8.GetString(input.ReadBytes((int)nl));if(!SafeName(name)||!names.Add(name))throw new InvalidDataException("Unsafe or duplicate payload path.");files.Add(name,input.ReadBytes((int)dl));}if(input.BaseStream.Position!=bytes.Length)throw new InvalidDataException("Trailing payload refused.");}
  if(!files.ContainsKey("manifest.json")||files["manifest.json"].Length>1048576||!files.ContainsKey("package.json")||!files.ContainsKey("scripts/install.js"))throw new InvalidDataException("Manifest or installer missing.");var manifest=Json.Deserialize<Dictionary<string,object>>(Utf8.GetString(files["manifest.json"]));if((string)manifest["schema"]!="dom-tts-source/1"||(string)manifest["version"]!=PayloadIdentity.Version)throw new InvalidDataException();var approved=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(object raw in (IEnumerable)manifest["files"]){var item=(Dictionary<string,object>)raw;string name=(string)item["path"],hash=(string)item["sha256"];if(!SafeName(name)||name=="manifest.json"||!approved.Add(name)||!files.ContainsKey(name)||Hash(files[name])!=hash)throw new InvalidDataException("Manifest file refused.");}if(approved.Count!=files.Count-1||(string)Json.Deserialize<Dictionary<string,object>>(Utf8.GetString(files["package.json"]))["version"]!=PayloadIdentity.Version)throw new InvalidDataException("Version or count refused.");return files;
 }
 // Windows command-line quoting; callers supply a fixed program and separate arguments.
 static string Quote(string value){var result=new StringBuilder("\"");int slashes=0;foreach(char ch in value){if(ch=='\\'){slashes++;continue;}if(ch=='\"'){result.Append('\\',slashes*2+1);result.Append(ch);}else{result.Append('\\',slashes);result.Append(ch);}slashes=0;}result.Append('\\',slashes*2);result.Append('"');return result.ToString();}
 static string Run(string exe,string[] args,int timeout){var joined=new StringBuilder();foreach(string arg in args){if(joined.Length>0)joined.Append(' ');joined.Append(Quote(arg));}var start=new ProcessStartInfo(exe,joined.ToString()){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};foreach(string key in new[]{"NODE_OPTIONS","NODE_PATH","ELECTRON_RUN_AS_NODE","PSModulePath"})start.EnvironmentVariables.Remove(key);var output=new StringBuilder();using(var child=new Process{StartInfo=start}){DataReceivedEventHandler collect=(s,e)=>{if(e.Data!=null)lock(output){if(output.Length<16384)output.AppendLine(e.Data.Substring(0,Math.Min(e.Data.Length,16384-output.Length)));}};child.OutputDataReceived+=collect;child.ErrorDataReceived+=collect;if(!child.Start())throw new InvalidOperationException();child.BeginOutputReadLine();child.BeginErrorReadLine();if(!child.WaitForExit(timeout)){try{child.Kill();if(!child.WaitForExit(5000))throw new OwnedProcessUnsettledException();}catch(OwnedProcessUnsettledException){throw;}catch{throw new OwnedProcessUnsettledException();}throw new InvalidOperationException("Owned installer timed out. Inspect managed recovery state.");}child.WaitForExit();string text;lock(output)text=output.ToString();if(child.ExitCode!=0)throw new InvalidOperationException(text.Length>0?text:"Selected runtime or installer refused the operation.");return text;}}
 static bool Trusted(string file){NoLinks(file);if(!File.Exists(file)||System.Text.RegularExpressions.Regex.IsMatch(file,@"[\x00-\x1f\x7f]"))return false;string powershell=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"WindowsPowerShell","v1.0","powershell.exe");string command="$ErrorActionPreference='Stop'; $env:PSModulePath=Join-Path $PSHOME 'Modules'; $s=Get-AuthenticodeSignature -LiteralPath '"+file.Replace("'","''")+"'; if($s.Status -eq 'Valid'){[Console]::Write('Valid')}else{exit 3}";try{return Run(powershell,new[]{"-NoProfile","-NonInteractive","-Command",command},15000).Trim()=="Valid";}catch{return false;}}
 static string Stage(Dictionary<string,byte[]> files){string parent=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"42uk","DomTTSSetup");NoLinks(parent);Directory.CreateDirectory(parent);string stage=Path.Combine(parent,"candidate-"+Guid.NewGuid().ToString("N"));var security=new DirectorySecurity();var user=WindowsIdentity.GetCurrent().User;security.SetOwner(user);security.SetAccessRuleProtection(true,false);foreach(var sid in new[]{user,new SecurityIdentifier("S-1-5-18"),new SecurityIdentifier("S-1-5-32-544")})security.AddAccessRule(new FileSystemAccessRule(sid,FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));Directory.CreateDirectory(stage,security);NoLinks(stage);foreach(var item in files){string target=Path.GetFullPath(Path.Combine(stage,item.Key.Replace('/',Path.DirectorySeparatorChar)));if(!target.StartsWith(stage+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException();NoLinks(target);Directory.CreateDirectory(Path.GetDirectoryName(target));NoLinks(Path.GetDirectoryName(target));using(var file=new FileStream(target,FileMode.CreateNew,FileAccess.Write,FileShare.None)){file.Write(item.Value,0,item.Value.Length);file.Flush(true);}}return stage;}
 static void CheckTree(string folder){NoLinks(folder);foreach(string entry in Directory.GetFileSystemEntries(folder)){NoLinks(entry);if(Directory.Exists(entry))CheckTree(entry);}}
 static string Operate(string node,string target,string action,bool apply){if(!Path.IsPathRooted(node)||Path.GetFileName(node).ToLowerInvariant()!="node.exe"||!Trusted(node))throw new InvalidOperationException("Select an already-installed trusted signed node.exe; no runtime is downloaded.");if(target!="codex"&&target!="claude")throw new InvalidOperationException("Select the current user's Codex or Claude skill target.");if(action!="install"&&action!="uninstall"&&action!="rollback"&&action!="recover")throw new InvalidOperationException("Unknown managed action.");string version=Run(node,new[]{"--version"},10000).Trim();int major;if(version.Length<2||!Int32.TryParse(version.Substring(1).Split('.')[0],out major)||major<18)throw new InvalidOperationException("Node 18 or newer required.");string stage=Stage(Payload());bool settled=false;try{var args=new List<string>{Path.Combine(stage,"scripts","install.js"),"--target",target,"--action",action};if(!apply)args.Add("--dry-run");string result=Run(node,args.ToArray(),300000);settled=true;return result;}catch(OwnedProcessUnsettledException){throw;}catch{settled=true;throw;}finally{if(settled&&Directory.Exists(stage)){string parent=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"42uk","DomTTSSetup");if(Path.GetDirectoryName(stage)!=parent||!Path.GetFileName(stage).StartsWith("candidate-"))throw new InvalidDataException("Unexpected staging cleanup path.");CheckTree(stage);Directory.Delete(stage,true);}}}
 [STAThread] static int Main(string[] args){try{string self=Assembly.GetExecutingAssembly().Location;if(!Trusted(self)){Console.Error.WriteLine("Dom TTS setup requires a reviewed trusted signed executable. Development compilations are not installable.");return 1;}if(args.Length==0){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new SetupForm());return 0;}var options=new Dictionary<string,string>();for(int i=0;i<args.Length;i+=2){if(i+1>=args.Length||!new HashSet<string>{"--node","--target","--action","--apply"}.Contains(args[i])||options.ContainsKey(args[i]))throw new InvalidOperationException("Named setup options required.");options.Add(args[i],args[i+1]);}if(!options.ContainsKey("--node")||!options.ContainsKey("--target"))throw new InvalidOperationException("Choose explicit --node and --target.");string apply=options.ContainsKey("--apply")?options["--apply"]:"false";if(apply!="true"&&apply!="false")throw new InvalidOperationException("--apply requires true or false.");Console.WriteLine(Operate(options["--node"],options["--target"],options.ContainsKey("--action")?options["--action"]:"install",apply=="true"));return 0;}catch(Exception error){Console.Error.WriteLine(error.Message);return 1;}}
 class SetupForm:Form {
  readonly TextBox node=new TextBox{Left=20,Top=62,Width=465};readonly ComboBox target=new ComboBox{Left=20,Top=100,Width=160,DropDownStyle=ComboBoxStyle.DropDownList};readonly ComboBox action=new ComboBox{Left=200,Top=100,Width=170,DropDownStyle=ComboBoxStyle.DropDownList};readonly TextBox output=new TextBox{Left=20,Top=185,Width=570,Height=210,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical};readonly Button apply=new Button{Text="Apply reviewed action",Left=220,Top=140,Width=175,Enabled=false};string previewKey;
  public SetupForm(){Text="Dom TTS "+PayloadIdentity.Version+" per-user setup";Width=630;Height=460;Controls.Add(new Label{Text="Select your trusted Node runtime. Preview before applying. No audio or startup changes.",Left=20,Top=20,Width=580,Height=35});Controls.Add(node);var browse=new Button{Text="Browse",Left=495,Top=60,Width=95};browse.Click+=(s,e)=>{using(var picker=new OpenFileDialog{Filter="Node runtime (node.exe)|node.exe",CheckFileExists=true})if(picker.ShowDialog()==DialogResult.OK)node.Text=picker.FileName;};Controls.Add(browse);target.Items.AddRange(new object[]{"codex","claude"});target.SelectedIndex=0;action.Items.AddRange(new object[]{"install","rollback","uninstall","recover"});action.SelectedIndex=0;Controls.Add(target);Controls.Add(action);var preview=new Button{Text="Preview",Left=20,Top=140,Width=175};preview.Click+=(s,e)=>{try{output.Text=Operate(node.Text,(string)target.SelectedItem,(string)action.SelectedItem,false);previewKey=Key();apply.Enabled=true;}catch(Exception error){output.Text=error.Message;apply.Enabled=false;}};apply.Click+=(s,e)=>{if(previewKey!=Key()){apply.Enabled=false;return;}try{output.Text=Operate(node.Text,(string)target.SelectedItem,(string)action.SelectedItem,true);}catch(Exception error){output.Text=error.Message;}finally{apply.Enabled=false;}};node.TextChanged+=(s,e)=>apply.Enabled=false;target.SelectedIndexChanged+=(s,e)=>apply.Enabled=false;action.SelectedIndexChanged+=(s,e)=>apply.Enabled=false;Controls.Add(preview);Controls.Add(apply);Controls.Add(output);}
  string Key(){return node.Text+"\n"+target.SelectedItem+"\n"+action.SelectedItem;}
 }
